/* ============================================
   AGENT PLAN COMPONENT
   A collapsible checklist of an agent's task:
   a progress header and one row per step.

   The container stays neutral, like ToolCall —
   colour lives in each step's indicator, so a
   long plan reads as a list rather than a wall
   of tinted rows. A thin connector ties the
   indicators into one path through the task.
   ============================================ */

.ds-agent-plan {
  display: flex;
  flex-direction: column;
  width: 100%;
  background-color: var(--color-bg-container-primary);
  border: var(--border-025) solid var(--color-bg-container-border);
  /* The chat furniture's shared 24px shell — see ToolCall. */
  border-radius: var(--radius-600);
  overflow: hidden;
}

/* ============================================
   HEADER
   ============================================ */

.ds-agent-plan__header {
  display: flex;
  align-items: center;
  gap: var(--gap-200);
  width: 100%;
  /* 20px sides — the card family's shared content inset. */
  padding: var(--padding-200) var(--padding-500);
  background: none;
  border: none;
  text-align: left;
  cursor: pointer;
  transition: background-color var(--motion-duration-fast) var(--motion-ease-standard);
}

.ds-agent-plan__header:hover {
  background-color: var(--color-bg-container-secondary);
}

.ds-agent-plan__header:focus-visible {
  outline: 2px solid var(--color-action-primary-bg);
  outline-offset: -2px;
}

.ds-agent-plan__title {
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--color-text-primary);
  font-family: var(--font-paragraph-sm-emphasis-family);
  font-size: var(--font-paragraph-sm-emphasis-size);
  font-weight: var(--font-paragraph-sm-emphasis-weight);
  line-height: var(--font-paragraph-sm-emphasis-line-height);
  letter-spacing: var(--font-paragraph-sm-emphasis-letter-spacing);
}

.ds-agent-plan__count {
  flex: none;
  color: var(--color-text-tertiary);
  font-family: var(--font-paragraph-sm-family);
  font-size: var(--font-paragraph-sm-size);
  font-weight: var(--font-paragraph-sm-weight);
  line-height: var(--font-paragraph-sm-line-height);
  letter-spacing: var(--font-paragraph-sm-letter-spacing);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

.ds-agent-plan__chevron {
  --icon-size: var(--icon-size-500);

  flex: none;
  color: var(--color-icon-secondary);
  transition: transform var(--motion-duration-slow) var(--motion-ease-standard);
}

.ds-agent-plan--open .ds-agent-plan__chevron {
  transform: rotate(180deg);
}

/* ============================================
   PANEL
   Same grid-rows collapse as ToolCall, so the
   list opens and closes without measuring.
   ============================================ */

.ds-agent-plan__panel {
  display: grid;
  grid-template-rows: 0fr;
  visibility: hidden;
  transition:
    grid-template-rows var(--motion-duration-slow) var(--motion-ease-standard),
    visibility var(--motion-duration-slow) var(--motion-ease-standard);
}

.ds-agent-plan--open .ds-agent-plan__panel {
  grid-template-rows: 1fr;
  visibility: visible;
}

.ds-agent-plan__content {
  overflow: hidden;
  min-height: 0;
}

.ds-agent-plan--open .ds-agent-plan__content {
  border-top: var(--border-025) solid var(--color-divider);
}

/* ============================================
   STEPS
   ============================================ */

.ds-agent-plan__steps {
  display: flex;
  flex-direction: column;
  margin: 0;
  padding: var(--padding-300) var(--padding-500);
  list-style: none;
}

.ds-agent-plan__step {
  position: relative;
  display: flex;
  align-items: flex-start;
  gap: var(--gap-200);
  padding: var(--padding-100) 0;
}

/* Connector — a thin line linking each indicator to the next */
.ds-agent-plan__step:not(:last-child)::before {
  content: '';
  position: absolute;
  top: calc(var(--padding-100) + var(--icon-size-500));
  bottom: calc(-1 * var(--padding-100));
  left: calc(var(--icon-size-500) / 2);
  width: var(--border-025);
  background-color: var(--color-divider);
}

.ds-agent-plan__indicator {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: none;
  /* Fixed box: the active step's spinner (16px) is smaller than the step
     icons (20px), so without this the column narrows and the spinner drifts
     off the connector's centre line. */
  width: var(--icon-size-500);
  height: var(--icon-size-500);
  color: var(--color-icon-secondary);
}

.ds-agent-plan__indicator .material-symbols-rounded {
  --icon-size: var(--icon-size-500);
}

.ds-agent-plan__step-body {
  display: flex;
  flex-direction: column;
  min-width: 0;
  /* Align the first text line with the indicator's optical centre */
  padding-top: calc((var(--icon-size-500) - var(--font-paragraph-sm-line-height)) / 2);
}

.ds-agent-plan__label {
  color: var(--color-text-primary);
  font-family: var(--font-paragraph-sm-family);
  font-size: var(--font-paragraph-sm-size);
  font-weight: var(--font-paragraph-sm-weight);
  line-height: var(--font-paragraph-sm-line-height);
  letter-spacing: var(--font-paragraph-sm-letter-spacing);
}

.ds-agent-plan__detail {
  color: var(--color-text-tertiary);
  font-family: var(--font-paragraph-sm-family);
  font-size: var(--font-paragraph-sm-size);
  font-weight: var(--font-paragraph-sm-weight);
  line-height: var(--font-paragraph-sm-line-height);
  letter-spacing: var(--font-paragraph-sm-letter-spacing);
}

/* ============================================
   STEP STATES
   ============================================ */

.ds-agent-plan__step--pending .ds-agent-plan__indicator {
  color: var(--color-status-neutral-icon);
}

.ds-agent-plan__step--completed .ds-agent-plan__indicator {
  color: var(--color-status-positive-icon);
}

.ds-agent-plan__step--completed .ds-agent-plan__label {
  color: var(--color-text-tertiary);
}

.ds-agent-plan__step--active .ds-agent-plan__indicator {
  color: var(--color-status-info-icon);
}

.ds-agent-plan__step--active .ds-agent-plan__label {
  font-family: var(--font-paragraph-sm-emphasis-family);
  font-weight: var(--font-paragraph-sm-emphasis-weight);
  letter-spacing: var(--font-paragraph-sm-emphasis-letter-spacing);
}

.ds-agent-plan__step--failed .ds-agent-plan__indicator {
  color: var(--color-status-error-icon);
}

.ds-agent-plan__step--failed .ds-agent-plan__label {
  color: var(--color-status-error-text);
}

/* ============================================
   SCREEN READER TEXT
   Status is colour + glyph for sighted users;
   this span announces it.
   ============================================ */

.ds-agent-plan__sr {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

/* Icons take the colour of the text around them. Explicit, not just
   inherited by default: a consumer stylesheet that sets a colour on
   .material-symbols-rounded itself (a common global default) would
   otherwise override inheritance and detach the icon from the state
   colours this component sets on its parents. */
.ds-agent-plan .material-symbols-rounded {
  color: inherit;
}

'use client';

import React, { useCallback, useId, useState } from 'react';
import { Spinner } from '../Spinner/Spinner';
import './AgentPlan.css';
import '../../fonts/material-symbols.css';

export type AgentPlanStepStatus = 'pending' | 'active' | 'completed' | 'failed';

export interface AgentPlanStep {
  /** What this step does, in one line. */
  label: string;
  /** Where the step has got to. Defaults to `pending`. */
  status?: AgentPlanStepStatus;
  /** Optional supporting line under the label, e.g. the file it touched. */
  detail?: string;
}

/** The glyph shown for a settled step; the active step gets a spinner instead. */
const STEP_ICONS: Record<Exclude<AgentPlanStepStatus, 'active'>, string> = {
  pending: 'circle',
  completed: 'check_circle',
  failed: 'error',
};

/** Announced to screen readers alongside each step's label. */
const STEP_STATUS_TEXT: Record<AgentPlanStepStatus, string> = {
  pending: 'Not started',
  active: 'In progress',
  completed: 'Completed',
  failed: 'Failed',
};

/** Props owned by AgentPlan itself — everything else falls through to the root element. */
type AgentPlanOwnProps = {
  /** The plan, in order. Step status drives each row's indicator and colour. */
  steps: AgentPlanStep[];
  /**
   * Header text. Left unset, it is computed from the steps —
   * "3 steps left", or "All steps complete" once everything is done.
   */
  title?: string;
  /** Open state for controlled use. Pair with `onOpenChange`. */
  open?: boolean;
  /** Open state for uncontrolled use. */
  defaultOpen?: boolean;
  /** Fires whenever the step list opens or closes. */
  onOpenChange?: (open: boolean) => void;
  /** Additional CSS classes */
  className?: string;
};

export interface AgentPlanProps
  extends AgentPlanOwnProps,
    Omit<React.ComponentPropsWithoutRef<'div'>, keyof AgentPlanOwnProps> {}

/**
 * AgentPlan shows the steps an agent intends to take and where it has got to:
 * a collapsible checklist with one row per step, a live progress readout in
 * the header, and completed work ticked off as the run advances.
 *
 * It complements the other agent primitives — AgentStatus says what is
 * happening right now, ToolCall records one action, AgentPlan holds the
 * whole task.
 */
export const AgentPlan = React.forwardRef<HTMLDivElement, AgentPlanProps>(
  (
    {
      steps,
      title,
      open,
      defaultOpen = true,
      onOpenChange,
      className = '',
      ...rest
    },
    ref,
  ) => {
    const baseClass = 'ds-agent-plan';
    const id = useId();
    const panelId = `${id}-panel`;
    const triggerId = `${id}-trigger`;

    const isControlled = open !== undefined;
    const [uncontrolledOpen, setUncontrolledOpen] = useState(defaultOpen);
    const isOpen = isControlled ? open : uncontrolledOpen;

    const toggle = useCallback(() => {
      const next = !isOpen;
      if (!isControlled) setUncontrolledOpen(next);
      onOpenChange?.(next);
    }, [isOpen, isControlled, onOpenChange]);

    const total = steps.length;
    const completed = steps.filter((step) => step.status === 'completed').length;
    const remaining = total - completed;
    const resolvedTitle =
      title ??
      (total > 0 && remaining === 0
        ? 'All steps complete'
        : `${remaining} step${remaining === 1 ? '' : 's'} left`);

    const classes = [baseClass, isOpen ? `${baseClass}--open` : '', className]
      .filter(Boolean)
      .join(' ');

    return (
      <div {...rest} ref={ref} className={classes}>
        <button
          type="button"
          id={triggerId}
          className={`${baseClass}__header`}
          aria-expanded={isOpen}
          aria-controls={panelId}
          onClick={toggle}
        >
          <span className={`${baseClass}__title`}>{resolvedTitle}</span>
          {total > 0 && (
            <span className={`${baseClass}__count`}>
              {completed}/{total}
            </span>
          )}
          <span className={`${baseClass}__chevron material-symbols-rounded`} aria-hidden="true">
            expand_more
          </span>
        </button>

        <div
          className={`${baseClass}__panel`}
          id={panelId}
          role="region"
          aria-labelledby={triggerId}
        >
          <div className={`${baseClass}__content`}>
            <ol className={`${baseClass}__steps`}>
              {steps.map((step, index) => {
                const status = step.status ?? 'pending';
                return (
                  <li
                    key={index}
                    className={`${baseClass}__step ${baseClass}__step--${status}`}
                    aria-current={status === 'active' ? 'step' : undefined}
                  >
                    <span className={`${baseClass}__indicator`} aria-hidden="true">
                      {status === 'active' ? (
                        <Spinner size="sm" variant="inherit" />
                      ) : (
                        <span className="material-symbols-rounded">{STEP_ICONS[status]}</span>
                      )}
                    </span>
                    <span className={`${baseClass}__step-body`}>
                      <span className={`${baseClass}__label`}>{step.label}</span>
                      {step.detail && (
                        <span className={`${baseClass}__detail`}>{step.detail}</span>
                      )}
                    </span>
                    <span className={`${baseClass}__sr`}>{STEP_STATUS_TEXT[status]}</span>
                  </li>
                );
              })}
            </ol>
          </div>
        </div>
      </div>
    );
  },
);

AgentPlan.displayName = 'AgentPlan';
